<section class="yv-status-page"><div class="yv-status-card"><div class="yv-status-icon" style="color:#14a66e;background:#eafff6"><?= icon('check-circle',34) ?></div><div class="yv-kicker">Sipariş onayı</div><h1><?= $method==='bank_transfer'?'Siparişiniz oluşturuldu.':'Ödemeniz başarıyla tamamlandı.' ?></h1><?php if($orderNumber): ?><p>Sipariş numaranız: <strong><?= e($orderNumber) ?></strong></p><?php endif; ?><?php if($method==='bank_transfer'&&!empty($bankAccounts)): ?><div style="text-align:left;margin-top:20px"><h3 style="font-size:14px"><?= icon('inbox',14) ?> Havale / EFT Bilgileri</h3><?php foreach($bankAccounts as $acc): ?><div style="padding:13px;margin-top:8px;border:1px solid #e4e8f1;border-radius:13px;background:#f8f9fd"><strong style="font-size:10px"><?= e($acc['bank_name']) ?></strong><div style="font-size:8px;color:#6f7990;margin-top:5px"><?= e($acc['account_holder']) ?></div><div style="font-size:9px;margin-top:4px"><?= e($acc['iban']) ?></div></div><?php endforeach; ?></div><?php endif; ?><div class="yv-status-actions"><a class="yv-btn yv-btn-primary" href="/siparislerim"><?= icon('package',12) ?> Siparişlerim</a><a class="yv-btn yv-btn-light" href="/">Ana sayfa</a></div></div></section>